<template><form class="panel" style="width:min(100%,420px)" @submit.prevent="submit"><p class="eyebrow">Start clearly</p><h2>Create account</h2><label>Name</label><input v-model="name" required><label>Email</label><input v-model="email" type="email" required><label>Password</label><input v-model="password" type="password" required><button class="primary" type="submit">Register</button></form></template>
<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; const name=ref(''); const email=ref(''); const password=ref(''); const router=useRouter(); async function submit(){ await useAuthStore().register(email.value,name.value,password.value); await router.push('/login') }</script>
